Translate the following GNU C++0x code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <iostream>
#include <string>
#include <cstdlib>
#include <vector>
#include <cmath>
using namespace std;

typedef long long int_type;
#define container_size(c) (int)(c).size()

int_type get_gcd(int_type a, int_type b) {
    while( b != 0 )
        a %= b, swap(a, b);
    return a;
}

int main() {
    int_type X, Y, N; cin >> X >> Y >> N;
    int_type bestA, bestB;
    double minDiff = 1e12;
    for(int_type b = 1; b <= N; b++) {
        int_type left = 0, right = 100000;
        int_type a = 0;
        while( left <= right ) {
            int_type mid = (left + right) >> 1;
            if( mid * Y <= X * b )
                a = mid, left = mid + 1;
            else
                right = mid - 1;
        }
        left = 0, right = 100000;
        int_type a2 = 0, b2 = b;
        while( left <= right ) {
            int_type mid = (left + right) >> 1;
            if( mid * Y < X * b )
                left = mid + 1;
            else
                a2 = mid, right = mid - 1;
        }
        double diff2 = abs(double(a2)/double(b2) - double(X)/double(Y));
        double diff1 = abs(double(a)/double(b) - double(X)/double(Y));
        if( diff2 + 1e-8 < diff1)
            a = a2, b = b2, diff1 = diff2;
        int_type g = get_gcd(a, b);
        if( diff1 < minDiff )
            bestA = a / g, bestB = b / g, minDiff = diff1;
    }
    cout << bestA << "/" << bestB;
    return 0;
}
